import re
import sys

from verkle_best_specializations_dynamic_programming import print_best_specializations

# Usage: python mpt_best_specializations_dynamic_programming.py <trie-stats output>
# Data is generated by `go run ./database/mpt/tool trie-stats <dir>` (run from ../go).

# NOTE: These sizes are based on the branch node encoders in ../go/database/mpt/nodes.go and need to be manually updated if the implementation changes.

# The size of a node id stored in branch nodes
ID_SIZE = 6
# The size of a hash
HASH_SIZE = 32
# The size of the index for a child stored in sparse branch nodes
CHILD_INDEX_SIZE = 1
# The size of the bit mask marking embedded children
EMBEDDED_MASK_SIZE = 2
# The number of children of a full branch node
BRANCH_CHILDREN = 16

# Size of a full branch node with BranchNodeEncoderWithChildHashes (HashStoredWithParent)
FULL_BRANCH_WITH_CHILD_HASHES_SIZE = (
    BRANCH_CHILDREN * (ID_SIZE + HASH_SIZE) + EMBEDDED_MASK_SIZE
)
# Size of a full branch node with BranchNodeEncoderWithNodeHash (HashStoredWithNode)
FULL_BRANCH_WITH_NODE_HASH_SIZE = BRANCH_CHILDREN * ID_SIZE + HASH_SIZE


def get_branch_sizes_with_child_hashes() -> list[int]:
    """Return branch node sizes for 0 to 16 children when hashes are stored with the parent."""
    sparse = [
        EMBEDDED_MASK_SIZE + n * (ID_SIZE + HASH_SIZE + CHILD_INDEX_SIZE)
        for n in range(BRANCH_CHILDREN)
    ]
    return [min(s, FULL_BRANCH_WITH_CHILD_HASHES_SIZE) for s in sparse] + [
        FULL_BRANCH_WITH_CHILD_HASHES_SIZE
    ]


def get_branch_sizes_with_node_hash() -> list[int]:
    """Return branch node sizes for 0 to 16 children when hashes are stored with the node."""
    sparse = [
        HASH_SIZE + n * (ID_SIZE + CHILD_INDEX_SIZE) for n in range(BRANCH_CHILDREN)
    ]
    return [min(s, FULL_BRANCH_WITH_NODE_HASH_SIZE) for s in sparse] + [
        FULL_BRANCH_WITH_NODE_HASH_SIZE
    ]


def load_branch_counts(path: str) -> list[int]:
    """Load the branch node fill counts from a `trie-stats` output file."""
    counts = [0] * (BRANCH_CHILDREN + 1)
    with open(path) as f:
        # only the branch fill lines start with "<children>: <count>"
        for m in re.finditer(r"^\s*(\d+):\s+(\d+)", f.read(), re.MULTILINE):
            counts[int(m.group(1))] = int(m.group(2))
    return counts


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"usage: {sys.argv[0]} <trie-stats output>")
    counts = load_branch_counts(sys.argv[1])
    print_best_specializations(
        "Branch (hash stored with parent)", counts, get_branch_sizes_with_child_hashes()
    )
    print_best_specializations(
        "Branch (hash stored with node)", counts, get_branch_sizes_with_node_hash()
    )
